Lemma xb_ok_ext : forall a b B, as_space_beg a = as_space_beg b -> as_regions a = as_regions b -> xb_ok b B -> xb_ok a B.
Proof. intros a b B. destruct a, b; cbn. intros -> -> H. exact H. Qed.

